BEGIN;
DO $test$
DECLARE u uuid:='00000000-0000-4000-8000-000000002191';u2 uuid:='00000000-0000-4000-8000-000000002192';a uuid;a2 uuid;pri uuid;sec uuid;x uuid;ch uuid;ch2 uuid;ep uuid;d timestamptz;cv timestamptz;v jsonb;p uuid;c uuid;p2 uuid;c2 uuid;token uuid;mid uuid;t uuid;t2 uuid;raw uuid;anchor uuid;at timestamptz;arr jsonb;z jsonb;scope text;tg uuid;fg uuid;legacy_before integer;
BEGIN
 INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(u,'inbox219@example.test','{"full_name":"Inbox 219"}'),(u2,'inbox219-foreign@example.test','{"full_name":"Foreign"}');
 SELECT account_id INTO STRICT a FROM public.profiles WHERE user_id=u;
 SELECT account_id INTO STRICT a2 FROM public.profiles WHERE user_id=u2;
 FOR i IN 1..3 LOOP
  INSERT INTO public.whatsapp_connections(account_id,provider,status,session_id,phone_identity,display_name,provider_metadata) VALUES(a,'openwa','ready','inbox219-'||i,CASE WHEN i<3 THEN '15550000191' ELSE '15550000192' END,'Session '||i,'{"secret":"never-return"}') RETURNING id,updated_at INTO x,d;
  INSERT INTO public.whatsapp_connection_credentials(account_id,connection_id,provider,base_url,api_key_encrypted) VALUES(a,x,'openwa','https://example.test','fixture') RETURNING updated_at INTO cv;
  v=public.inbox_enroll_verified_channel(a,u,x,'openwa',CASE WHEN i<3 THEN '15550000191' ELSE '15550000192' END,'inbox219-'||i,NULL,d,cv,clock_timestamp(),'fixture-'||i,i<>2);
  ep=(v->>'membership_id')::uuid;
  INSERT INTO public.inbox_native_namespace_proofs(account_id,provider,channel_id,connection_id,membership_id,namespace_key,evidence_ref) VALUES(a,'openwa',(v->>'channel_id')::uuid,x,ep,'fixture-shared','fixture');
  IF i=1 THEN pri=x;ch=(v->>'channel_id')::uuid;ELSIF i=2 THEN sec=x;ELSE ch2=(v->>'channel_id')::uuid;END IF;
 END LOOP;
 INSERT INTO public.contacts(user_id,account_id,phone,name) VALUES(u,a,'+15550000217','Fixture') RETURNING id INTO p;
 INSERT INTO public.conversations(user_id,account_id,contact_id,unread_count) VALUES(u,a,p,2) RETURNING id INTO c;
 INSERT INTO public.contacts(user_id,account_id,phone,name) VALUES(u2,a2,'+15550000218','Foreign') RETURNING id INTO p2;
 INSERT INTO public.conversations(user_id,account_id,contact_id) VALUES(u2,a2,p2) RETURNING id INTO c2;
 at=clock_timestamp();
 FOR i IN 1..3 LOOP
  token=gen_random_uuid();
  INSERT INTO public.whatsapp_webhook_event_receipts(account_id,connection_id,provider,provider_event_id,received_at,processing_token,processing_started_at) VALUES(a,CASE WHEN i=1 THEN pri WHEN i=2 THEN sec ELSE x END,'openwa','read219-'||i,clock_timestamp(),token,clock_timestamp());
  v=public.inbox_commit_canonical_inbound_context(a,CASE WHEN i=1 THEN pri WHEN i=2 THEN sec ELSE x END,'read219-'||i,token,c,'inbox219-'||i,NULL,'native219',true,'text','body',NULL,'15550000217@c.us',at,NULL,'{}',false,false);
  IF i<>2 AND v->>'state'<>'inserted' THEN RAISE EXCEPTION 'fixture %',v; END IF;
 END LOOP;
 SELECT id INTO STRICT t FROM public.inbox_threads WHERE account_id=a AND channel_id=ch AND conversation_id=c;
 SELECT id INTO STRICT t2 FROM public.inbox_threads WHERE account_id=a AND channel_id=ch2 AND conversation_id=c;
 INSERT INTO public.messages(conversation_id,sender_type,content_type,content_text,provider,connection_id,provider_message_id,created_at,media_url,reply_to_message_id)
 VALUES(c,'customer','text','unknown','openwa',pri,'unknown219',at,'https://evil.test/?token=secret',(SELECT last_message_id FROM public.inbox_threads WHERE id=t)) RETURNING id INTO raw;
 UPDATE public.contacts SET company='Fixture Company' WHERE id=p;
 UPDATE public.conversations SET assigned_agent_id=u WHERE id=c;
 INSERT INTO public.tags(user_id,account_id,name) VALUES(u,a,'SOF77') RETURNING id INTO tg;
 INSERT INTO public.tags(user_id,account_id,name) VALUES(u2,a2,'Other77') RETURNING id INTO fg;
 INSERT INTO public.contact_tags(contact_id,tag_id) VALUES(p,tg);
 EXECUTE 'SET LOCAL ROLE service_role';
 v=public.inbox_read_filtered_page(a,u,'threads','active',ch,NULL,'body',true,'mine',ARRAY[tg],'Fixture Company',NULL,1,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>1 OR v->'rows'->0->'payload'->>'id'<>t::text OR v->'rows'->0->'payload'->>'assigned_to_me'<>'true' THEN RAISE EXCEPTION 'exact channel + all filters %',v; END IF;
 v=public.inbox_read_filtered_page(a,u,'counts','active',ch,NULL,'body',true,'mine',ARRAY[tg],'Fixture Company',NULL,30,NULL,NULL);
 IF v->'counts'->>'threads'<>'1' OR v->'counts'->>'known_unread'<>'1' OR v->'counts'->>'lane_messages'<>'1' THEN RAISE EXCEPTION 'filtered counts %',v; END IF;
 v=public.inbox_read_filtered_page(a,u,'threads','active',ch,NULL,'unknown',false,'all',NULL,NULL,NULL,30,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>0 THEN RAISE EXCEPTION 'cross-lane preview'; END IF;
 v=public.inbox_read_filtered_page(a,u,'threads','active',NULL,NULL,NULL,false,'unassigned',NULL,NULL,NULL,30,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>0 THEN RAISE EXCEPTION 'assignment filter'; END IF;
 v=public.inbox_read_filtered_page(a,u,'threads','active',NULL,NULL,NULL,false,'all',ARRAY[fg],NULL,NULL,30,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>0 THEN RAISE EXCEPTION 'foreign tag filter'; END IF;
 v=public.inbox_read_filtered_page(a,u,'threads','active',ch2,NULL,NULL,false,'all',NULL,NULL,t,30,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>0 THEN RAISE EXCEPTION 'cross channel direct thread'; END IF;
 v=public.inbox_read_filtered_page(a,u,'tags','all',NULL,NULL,NULL,false,'all',NULL,NULL,NULL,30,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>1 OR v->'rows'->0->'payload'->>'id'<>tg::text THEN RAISE EXCEPTION 'foreign tag catalogue'; END IF;
 BEGIN PERFORM public.inbox_read_filtered_page(a,u2,'threads','active',NULL,NULL,NULL,false,'all',NULL,NULL,NULL,30,NULL,NULL); RAISE EXCEPTION 'foreign actor'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 IF has_function_privilege('authenticated','public.inbox_read_filtered_page(uuid,uuid,text,text,uuid,text,text,boolean,text,uuid[],text,uuid,integer,timestamptz,uuid)','EXECUTE') THEN RAISE EXCEPTION 'browser RPC'; END IF;
 -- Verify current visible scope can advance only the observed highwater;
 -- using another channel or actor is denied, sibling and legacy counts stay.
 IF public.inbox_mark_thread_read(a,u,t,ch2,1) IS NOT NULL THEN RAISE EXCEPTION 'wrong channel read'; END IF;
 BEGIN PERFORM public.inbox_mark_thread_read(a,u2,t,ch,1); RAISE EXCEPTION 'foreign actor read'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.inbox_mark_thread_read(a,u,t,ch,99999); RAISE EXCEPTION 'unobserved highwater accepted'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 v=public.inbox_read_history_with_reactions(a,u,'active',ch,NULL,t,30,NULL,NULL);
 IF v->'rows'->0->'payload'->'reactions'<>'[]'::jsonb THEN RAISE EXCEPTION 'empty reactions'; END IF;
 IF public.inbox_read_history_with_reactions(a,u,'active',ch2,NULL,t,30,NULL,NULL) IS NOT NULL THEN RAISE EXCEPTION 'wrong reaction scope'; END IF;
 IF has_function_privilege('authenticated','public.inbox_mark_thread_read(uuid,uuid,uuid,uuid,bigint)','EXECUTE') OR has_function_privilege('anon','public.inbox_read_history_with_reactions(uuid,uuid,text,uuid,uuid,uuid,integer,timestamptz,uuid)','EXECUTE') THEN RAISE EXCEPTION 'browser mutation RPC'; END IF;
 

 v=public.inbox_read_page(a,u,'channels','active',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>2 OR (v::text LIKE '%never-return%') THEN RAISE EXCEPTION 'catalog bound or secret %',v; END IF;
 v=public.inbox_read_page(a,u,'threads','active',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>2 THEN RAISE EXCEPTION 'channel threads %',v; END IF;
 anchor=(v->'rows'->0->>'row_id')::uuid;at=(v->'rows'->0->>'sort_at')::timestamptz;
 z=public.inbox_read_page(a,u,'threads','active',NULL,NULL,NULL,NULL,NULL,NULL,1,at,anchor);
 IF jsonb_array_length(z->'rows')<>1 OR (z->'rows'->0->>'row_id')::uuid=anchor THEN RAISE EXCEPTION 'keyset duplicate'; END IF;
 v=public.inbox_read_page(a,u,'history','active',ch,NULL,t,NULL,NULL,NULL,10,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>1 OR v::text LIKE '%native219%' OR v::text LIKE '%provider_chat_id%' THEN RAISE EXCEPTION 'history dedup/native secret %',v; END IF;
 mid=(v->'rows'->0->'payload'->>'id')::uuid;
 v=public.inbox_read_page(a,u,'observations','active',ch,NULL,t,NULL,NULL,NULL,10,NULL,NULL,mid);
 IF jsonb_array_length(v->'rows')<>2 OR v::text LIKE '%native219%' OR v::text LIKE '%read219-%' THEN RAISE EXCEPTION 'observations diagnostic scope'; END IF;
 IF public.inbox_read_page(a,u,'observations','active',ch,NULL,t,NULL,NULL,NULL,10,NULL,NULL,raw) IS NOT NULL THEN RAISE EXCEPTION 'foreign scoped observation'; END IF;
 v=public.inbox_read_page(a,u,'resolve','all',NULL,c,NULL,sec,NULL,NULL,10,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>1 OR v->'rows'->0->'payload'->>'channel_id'<>ch::text THEN RAISE EXCEPTION 'same-channel secondary legacy resolution %',v; END IF;
 v=public.inbox_read_page(a,u,'connections','active',ch,NULL,NULL,NULL,NULL,NULL,10,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'rows') r WHERE r->'payload'->>'ready'<>'true') THEN RAISE EXCEPTION 'connection readiness %',v; END IF;
 IF public.inbox_read_page(a,u,'history','active',ch2,NULL,t,NULL,NULL,NULL,10,NULL,NULL) IS NOT NULL THEN RAISE EXCEPTION 'cross channel history'; END IF;
 v=public.inbox_read_page(a,u,'history','unknown',NULL,c,NULL,NULL,NULL,NULL,10,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>1 OR v->'rows'->0->'payload'->>'id'<>raw::text OR v->'rows'->0->'payload'->>'reply_to_message_id' IS NOT NULL OR v->'rows'->0->'payload'->>'media_url' IS NOT NULL THEN RAISE EXCEPTION 'unknown or unsafe media/reply %',v; END IF;
 v=public.inbox_read_page(a,u,'counts','all',NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,NULL);
 IF (v->'counts'->>'source_messages')::int<>3 OR (v->'counts'->>'associated_messages')::int<>2 OR (v->'counts'->>'unresolved_messages')::int<>1 OR (v->'counts'->>'known_unread')::int<>2 THEN RAISE EXCEPTION 'counts conservation %',v; END IF;
 v=public.inbox_read_page(a,u,'resolve','all',NULL,c,NULL,NULL,NULL,NULL,10,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>3 THEN RAISE EXCEPTION 'ambiguous deep link %',v; END IF;
 IF public.inbox_read_page(a,u,'resolve','all',NULL,c2,NULL,NULL,NULL,NULL,10,NULL,NULL) IS NOT NULL THEN RAISE EXCEPTION 'foreign parent'; END IF;
 BEGIN PERFORM public.inbox_read_page(a,u2,'threads','active',NULL,NULL,NULL,NULL,NULL,NULL,10,NULL,NULL);RAISE EXCEPTION 'foreign actor'; EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_function_privilege('authenticated','public.inbox_read_page(uuid,uuid,text,text,uuid,uuid,uuid,uuid,text,text,integer,timestamptz,uuid,uuid)','EXECUTE') THEN RAISE EXCEPTION 'browser RPC'; END IF;
 EXECUTE 'RESET ROLE';
 INSERT INTO public.message_reactions(message_id,conversation_id,actor_type,actor_id,emoji) VALUES(mid,c,'agent',u,'👍');
 EXECUTE 'SET LOCAL ROLE service_role';
 v=public.inbox_read_history_with_reactions(a,u,'active',ch,NULL,t,30,NULL,NULL);
 IF v->'rows'->0->'payload'->'reactions'->0->>'emoji'<>'👍' OR v->'rows'->0->'payload'->'reactions'->0->>'mine'<>'true' THEN RAISE EXCEPTION 'scoped reaction projection %',v; END IF;
 SELECT unread_count INTO STRICT legacy_before FROM public.conversations WHERE id=c;
 v=public.inbox_mark_thread_read(a,u,t,ch,1);
 IF v->>'read_watermark'<>'1' OR v->>'unread_count_known'<>'0' THEN RAISE EXCEPTION 'read watermark %',v; END IF;
 v=public.inbox_mark_thread_read(a,u,t,ch,0);
 IF v->>'read_watermark'<>'1' THEN RAISE EXCEPTION 'watermark regressed'; END IF;
 IF (SELECT unread_count_known FROM public.inbox_threads WHERE id=t2)<>1 OR (SELECT unread_count FROM public.conversations WHERE id=c)<>legacy_before THEN RAISE EXCEPTION 'sibling or legacy unread cleared'; END IF;
 EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM public.inbox_thread_changes WHERE account_id=a AND thread_id=t AND revision>1) THEN RAISE EXCEPTION 'missing thread signal'; END IF;
 IF has_table_privilege('authenticated','public.inbox_thread_changes','INSERT') OR has_table_privilege('anon','public.inbox_thread_changes','SELECT') THEN RAISE EXCEPTION 'signal privileges'; END IF;
 PERFORM set_config('request.jwt.claim.sub',u2::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF EXISTS(SELECT 1 FROM public.inbox_thread_changes WHERE account_id=a) THEN RAISE EXCEPTION 'foreign realtime signal leaked'; END IF;
 EXECUTE 'RESET ROLE';
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF NOT EXISTS(SELECT 1 FROM public.inbox_thread_changes WHERE account_id=a AND thread_id=t) THEN RAISE EXCEPTION 'own signal not visible'; END IF;
 EXECUTE 'RESET ROLE';
 UPDATE public.profiles SET account_role='viewer' WHERE user_id=u;
 EXECUTE 'SET LOCAL ROLE service_role';
 BEGIN PERFORM public.inbox_mark_thread_read(a,u,t,ch,1); RAISE EXCEPTION 'viewer read mutation'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 EXECUTE 'RESET ROLE';
 UPDATE public.profiles SET account_role='owner' WHERE user_id=u;
 
 UPDATE public.whatsapp_connections SET status='disconnected' WHERE id IN(pri,sec);
 v=public.inbox_read_page(a,u,'history','historical',ch,NULL,t,NULL,NULL,NULL,10,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>1 THEN RAISE EXCEPTION 'historical history lost'; END IF;
 v=public.inbox_read_page(a,u,'connections','historical',ch,NULL,NULL,NULL,NULL,NULL,10,NULL,NULL);
 IF jsonb_array_length(v->'rows')<>2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'rows') r WHERE r->'payload'->>'ready'<>'false') THEN RAISE EXCEPTION 'historical connections %',v; END IF;
 IF public.inbox_read_page(a,u,'history','active',ch,NULL,t,NULL,NULL,NULL,10,NULL,NULL) IS NOT NULL THEN RAISE EXCEPTION 'stale active scope'; END IF;
 IF public.inbox_mark_thread_read(a,u,t,ch,1) IS NOT NULL THEN RAISE EXCEPTION 'historical read write'; END IF;
END $test$;

SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK;
